import{c as n,Q as s,j as e,m as l}from"./chunks/framework.BPKcPtvA.js";const u=JSON.parse('{"title":"ReAct 状态机控制流","description":"","frontmatter":{},"headers":[],"relativePath":"04-agent-architectures/react-flow.md","filePath":"04-agent-architectures/react-flow.md"}'),t={name:"04-agent-architectures/react-flow.md"};function i(p,a,r,o,c,h){return s(),e("div",null,[...a[0]||(a[0]=[l(`<h1 id="react-状态机控制流" tabindex="-1">ReAct 状态机控制流 <a class="header-anchor" href="#react-状态机控制流" aria-label="Permalink to &quot;ReAct 状态机控制流&quot;">​</a></h1><blockquote><p>感知-思考-行动循环 —— Agent 认知架构的核心范式</p></blockquote><h2 id="react-范式" tabindex="-1">ReAct 范式 <a class="header-anchor" href="#react-范式" aria-label="Permalink to &quot;ReAct 范式&quot;">​</a></h2><p>ReAct（Reasoning + Acting）是当前 Agent 系统最核心的认知范式，将大模型的推理能力与工具调用能力交织进行。</p><h3 id="核心理念" tabindex="-1">核心理念 <a class="header-anchor" href="#核心理念" aria-label="Permalink to &quot;核心理念&quot;">​</a></h3><p>传统 LLM 使用是「一次推理、一次输出」，而 ReAct Agent 在一个循环中交替执行：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>观察 (Observation) → 思考 (Thought) → 行动 (Action) → 观察 (Observation) → ...</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="react-循环的完整状态机" tabindex="-1">ReAct 循环的完整状态机 <a class="header-anchor" href="#react-循环的完整状态机" aria-label="Permalink to &quot;ReAct 循环的完整状态机&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────┐</span></span>
<span class="line"><span>│               Agent Loop                 │</span></span>
<span class="line"><span>│                                          │</span></span>
<span class="line"><span>│  ┌──────────┐    ┌──────────┐           │</span></span>
<span class="line"><span>│  │ OBSERVE  │───→│  THINK   │           │</span></span>
<span class="line"><span>│  │ 感知环境  │    │ 推理分析  │           │</span></span>
<span class="line"><span>│  └──────────┘    └──────────┘           │</span></span>
<span class="line"><span>│       ↑               │                  │</span></span>
<span class="line"><span>│       │               ↓                  │</span></span>
<span class="line"><span>│  ┌──────────┐    ┌──────────┐           │</span></span>
<span class="line"><span>│  │ REFLECT  │←───│   ACT    │           │</span></span>
<span class="line"><span>│  │ 反思评估  │    │ 执行动作  │           │</span></span>
<span class="line"><span>│  └──────────┘    └──────────┘           │</span></span>
<span class="line"><span>│       │               │                  │</span></span>
<span class="line"><span>│       └───────────────┘                  │</span></span>
<span class="line"><span>│                                          │</span></span>
<span class="line"><span>│         完成条件满足 → 终止               │</span></span>
<span class="line"><span>└─────────────────────────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br></div></div><h2 id="各阶段详解" tabindex="-1">各阶段详解 <a class="header-anchor" href="#各阶段详解" aria-label="Permalink to &quot;各阶段详解&quot;">​</a></h2><h3 id="_1-感知-observe" tabindex="-1">1. 感知 (Observe) <a class="header-anchor" href="#_1-感知-observe" aria-label="Permalink to &quot;1. 感知 (Observe)&quot;">​</a></h3><p>从环境中获取当前状态信息：</p><ul><li>用户输入的原始文本/图像</li><li>工具调用的返回结果</li><li>系统消息与历史对话</li><li>外部 API 返回的结构化数据</li><li>浏览器/桌面截图等视觉信号</li></ul><h3 id="_2-推理-think" tabindex="-1">2. 推理 (Think) <a class="header-anchor" href="#_2-推理-think" aria-label="Permalink to &quot;2. 推理 (Think)&quot;">​</a></h3><p>LLM 基于当前 Context 进行分析：</p><ul><li>理解用户意图与子目标</li><li>分析当前状态是否满足终止条件</li><li>决定下一步需要什么信息</li><li>规划需要调用哪些工具</li><li>评估风险与不确定性</li></ul><h3 id="_3-行动-act" tabindex="-1">3. 行动 (Act) <a class="header-anchor" href="#_3-行动-act" aria-label="Permalink to &quot;3. 行动 (Act)&quot;">​</a></h3><p>执行具体操作：</p><ul><li><strong>Tool Call</strong>：调用外部函数/API</li><li><strong>代码执行</strong>：运行生成的代码片段</li><li><strong>环境交互</strong>：点击、输入、滚动等 GUI 操作</li><li><strong>知识检索</strong>：查询向量数据库或文档库</li></ul><h3 id="_4-反思-reflect" tabindex="-1">4. 反思 (Reflect) <a class="header-anchor" href="#_4-反思-reflect" aria-label="Permalink to &quot;4. 反思 (Reflect)&quot;">​</a></h3><p>评估上一步行动的结果：</p><ul><li>结果是否符合预期？</li><li>是否需要修正策略？</li><li>是否存在幻觉或事实错误？</li><li>是否需要自我纠错？</li></ul><h2 id="react-prompt-模板" tabindex="-1">ReAct Prompt 模板 <a class="header-anchor" href="#react-prompt-模板" aria-label="Permalink to &quot;ReAct Prompt 模板&quot;">​</a></h2><p>典型的 ReAct Prompt 结构：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>System: You are an agent that can use tools.</span></span>
<span class="line"><span>        Use the following format:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        Thought: your reasoning about what to do next</span></span>
<span class="line"><span>        Action: the tool to use (must be one of [...])</span></span>
<span class="line"><span>        Action Input: the input to the tool</span></span>
<span class="line"><span>        Observation: the result of the action</span></span>
<span class="line"><span>        ... (repeat Thought/Action/Action Input/Observation)</span></span>
<span class="line"><span>        Thought: I now have the final answer</span></span>
<span class="line"><span>        Final Answer: the final answer to the user</span></span>
<span class="line"><span></span></span>
<span class="line"><span>User: &lt;task description&gt;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><h2 id="关键设计考量" tabindex="-1">关键设计考量 <a class="header-anchor" href="#关键设计考量" aria-label="Permalink to &quot;关键设计考量&quot;">​</a></h2><h3 id="终止条件" tabindex="-1">终止条件 <a class="header-anchor" href="#终止条件" aria-label="Permalink to &quot;终止条件&quot;">​</a></h3><ul><li><strong>显式</strong>：模型输出 <code>Final Answer</code> 或特殊终止 Token</li><li><strong>步数限制</strong>：设置最大迭代步数（如 15 步），防止无限循环</li><li><strong>超时机制</strong>：设置全局超时时间</li><li><strong>重复检测</strong>：检测连续相同的 Action，强制终止</li></ul><h3 id="context-管理" tabindex="-1">Context 管理 <a class="header-anchor" href="#context-管理" aria-label="Permalink to &quot;Context 管理&quot;">​</a></h3><p>ReAct 循环会在每轮追加 Observation 和新的 Thought/Action，Context 快速膨胀：</p><ul><li><strong>滑动窗口</strong>：仅保留最近 N 轮交互</li><li><strong>压缩/摘要</strong>：对历史步骤进行摘要压缩</li><li><strong>分层记忆</strong>：将历史交互移至外部记忆系统</li></ul><h3 id="思维链变体" tabindex="-1">思维链变体 <a class="header-anchor" href="#思维链变体" aria-label="Permalink to &quot;思维链变体&quot;">​</a></h3><table tabindex="0"><thead><tr><th>变体</th><th>描述</th></tr></thead><tbody><tr><td><strong>Self-Consistency</strong></td><td>多次采样取多数结果</td></tr><tr><td><strong>Tree of Thoughts</strong></td><td>树形探索多条推理路径</td></tr><tr><td><strong>Graph of Thoughts</strong></td><td>图结构，支持聚合与回溯</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">工程实践</p><p>ReAct 循环的数量通常通过 <code>max_steps</code> 参数控制。在工程中，将上限设为 10-15 步通常足够，过多的步数不仅消耗 Token，也增加了状态漂移的风险。</p></div>`,34)])])}const d=n(t,[["render",i]]);export{u as __pageData,d as default};
